Ext.define('BNK.view.common.ApprovalLineGridViewController', {
    extend: 'Ext.app.ViewController',
    alias: 'controller.common.approvallinegrid',

    config: {
        viewId: 'ApprovalLineGrid'
    },

    gridRenderer: function(value, record, dataIndex, cell, column) {
        if (!value) {
            return value;
        }

        switch(dataIndex) {
            case 'aprStcd': // 결재상태
            return CodeUtils.getText('INB016', value);
            case 'aprKndcd': // 결재종류
            return CodeUtils.getText('INB015', value);
        }
    }

});